/** Separate metadata generated by plan archiving; never rewrite a user-entered name. */
export function schemeCardHeading(plan) {
  const original = String(plan.name || '');
  if (!plan.archiveKey || !plan.archiveDate) return { title: original, metadata: '' };
  const suffix = ` · 日计划 · ${plan.archiveDate}`;
  if (!original.endsWith(suffix)) return { title: original, metadata: '' };
  const base = original.slice(0, -suffix.length);
  const day = /^(.*) · 第 (\d+) 天$/.exec(base);
  return { title: day?.[1] || base, metadata: `${day ? `第 ${day[2]} 天 · ` : ''}日计划 · ${plan.archiveDate}` };
}
